select t.script_id,t.script_id scriptId,t.script_type,t.script_type scriptType,t.script_name,t.script_name
scriptName,t.status_cd,t.status_cd statusCd,t.js_content,t.js_content jsContent,t.create_time createTime
from dt_script t
where 1 =1

    and t.script_id= #{scriptId}


    and t.script_type= #{scriptType}


    and t.script_name= #{scriptName}


    and t.status_cd= #{statusCd}


    and t.js_content= #{jsContent}

order by t.create_time desc

    limit #{page}, #{row}

